<?php get_header(); $type=get_post_type(); $is_programme=$type==='programme'; $is_project=$type==='project'; ?>
<main><section class="page-hero" data-mark="<?php echo $is_programme?'GO':'SRC'; ?>"><div class="container" data-reveal="left"><p class="eyebrow eyebrow-light"><?php echo $is_programme?'Programme detail':'Selected work'; ?></p><h1 class="display display-lg"><?php the_title(); ?></h1><p class="lede lede-light"><?php echo esc_html(get_the_excerpt()); ?></p></div></section>
